  "feedback": "总体评价，3-4句话概括主要优缺点",
  "dimensions": [
    {"dimension": "维度名称", "score": 4.5, "maxScore": 6, "comment": "具体评价"}
  ],
  "issues": [
    {"type": "grammar|vocabulary|structure|logic|task|tone", "original": "原文", "suggestion": "修改建议", "explanation": "中文解释", "severity": "high|medium|low"}
  ],
  "improvedVersion": "完整的修改后作文",
  "wordCount": 原始字数
